export const KPHX_T4_UNMAPPED_RAMP_POSITIONS = Object.freeze([["B1",20729,231.47],["B13A",20732,178.73],["B1B",20745,231.49],["B15A",20746,219.48],["B21",20749,270.24],["B15C",27989,179.78],["B26",28023,139.19],["B23",100216,270.32]]);

const poseByRampWedObjectId = new Map();
const posesByGate = new Map();

for (const [gate, rampWedObjectId, latitude, longitude, sourceHeadingDegrees] of RAW_SUPPORTED_T4_RAMPS) {
  const runtimePosition = kphxWedToRampReadyPosition(latitude, longitude, 0);
  const runtimeYawRadians = kphxXPlaneHeadingToRampReadyYawRadians(sourceHeadingDegrees);
  const pose = Object.freeze({
    gate,
    rampWedObjectId: String(rampWedObjectId),
    latitude,
    longitude,
    sourceHeadingDegrees,
    runtimePosition: Object.freeze(runtimePosition),
    runtimeYawRadians,
  });
  poseByRampWedObjectId.set(pose.rampWedObjectId, pose);
  const gateList = posesByGate.get(gate) || [];
  gateList.push(pose);
  posesByGate.set(gate, gateList);
}

for (const [gate, poses] of posesByGate) posesByGate.set(gate, Object.freeze(poses));

export function getKphxTerminal4GatePoseByRampWedObjectId(rampWedObjectId) {
  return poseByRampWedObjectId.get(String(rampWedObjectId)) || null;
}

export function getKphxTerminal4GatePoses(gate) {
  return posesByGate.get(String(gate).toUpperCase()) || Object.freeze([]);
}

export function getKphxTerminal4UniqueGatePose(gate) {
  const poses = getKphxTerminal4GatePoses(gate);
  if (poses.length !== 1) {
    throw new Error(`KPHX T4 gate ${gate} resolves to ${poses.length} ramp positions; use ramp WED object id`);
  }
  return poses[0];
}

export const KPHX_T4_SUPPORTED_RAMP_POSITION_IDS = Object.freeze(
  RAW_SUPPORTED_T4_RAMPS.map((entry) => String(entry[1])),
);
